corrected_code:
const { DynamoDBClient } = require('@aws-sdk/client-dynamodb');
const { DynamoDBDocumentClient, QueryCommand } = require('@aws-sdk/lib-dynamodb');

const docClient = DynamoDBDocumentClient.from(new DynamoDBClient({ region: 'us-east-1' }));

exports.handler = async (event) => {
  const authorizedTenantId = event.requestContext?.authorizer?.tenantId;
  const requestedTenantId = event.pathParameters?.tenantId;

  if (!authorizedTenantId || authorizedTenantId !== requestedTenantId) {
    return {
      statusCode: 403,
      body: JSON.stringify({ error: 'Access denied to target tenant audit trails' })
    };
  }

  const result = await docClient.send(new QueryCommand({
    TableName: 'AuditTrails',
    KeyConditionExpression: 'tenantId = :tid',
    ExpressionAttributeValues: { ':tid': requestedTenantId }
  }));

  return {
    statusCode: 200,
    body: JSON.stringify({ tenantId: requestedTenantId, records: result.Items })
  };
};
